{
  "name": "@grape-dev/grape-kit",
  "version": "0.3.1",
  "description": "Grape DevOps pipeline tools for coding agents — native HTTP transport (zero Python required), grape CLI optional. Turn any Git project into an AI-driven workflow, right inside your terminal agent.",
  "type": "module",
  "main": "src/server.mjs",
  "bin": {
    "grape-kit-mcp": "./grape-kit-mcp.mjs",
    "grape-kit": "./grape-kit.mjs"
  },
  "files": [
    "src",
    "skills",
    "grape-kit-mcp.mjs",
    "grape-kit.mjs",
    "LICENSE",
    "README.md"
  ],
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "test": "node --test test/*.test.mjs",
    "smoke": "node scripts/smoke.mjs"
  },
  "keywords": [
    "grape",
    "grape-cli",
    "grapedev",
    "mcp",
    "devops",
    "agent",
    "ai-native",
    "opencode",
    "hermes",
    "dsh",
    "pipeline",
    "a2a",
    "multi-agent"
  ],
  "license": "MIT",
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "repository": {
    "type": "git",
    "url": "git+https://gitcode.com/grape-dev/grape-kit.git"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.12.0"
  },
  "author": {
    "name": "grape-dev",
    "url": "https://gitcode.com/grape-dev"
  },
  "homepage": "https://www.grapedev.cn/",
  "bugs": {
    "url": "https://gitcode.com/grape-dev/grape-kit/issues"
  }
}
